mapper.sql:
WHERE t.created_by=#{owner}
   AND COALESCE(t.start_at,t.created_at)>=#{filters.start}
   AND COALESCE(t.start_at,t.created_at)<#{filters.end}
   AND t.id=#{filters.trainingId}
   AND t.category=#{filters.category}
   AND EXISTS(SELECT 1 FROM training_audience scope WHERE scope.training_id=t.id AND scope.department_id=#{filters.departmentId})
